import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"公眾頻道聊天規範","description":"公眾頻道聊天規範，請玩家們遵守。","frontmatter":{"title":"公眾頻道聊天規範","description":"公眾頻道聊天規範，請玩家們遵守。"},"headers":[],"relativePath":"rule/chat/index.md","filePath":"rule/chat.md"}'),t={name:"rule/chat/index.md"};function o(d,l,c,h,n,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="公眾頻道聊天規範" tabindex="-1">公眾頻道聊天規範 <a class="header-anchor" href="#公眾頻道聊天規範" aria-label="Permalink to &quot;公眾頻道聊天規範&quot;">​</a></h1><p>各位玩家好，這裡是個<b>公開</b>的伺服環境，您的每一句發言都會影響社群的風氣，為了維護伺服的遊玩體驗、營造良好的環境，讓玩家們都可以在此伺服開心的遊玩，因此希望各位玩家們遵守並多加配合!</p><p>同時頻道的發言也會同步至 <a href="/discord/">伺服Discord</a><br> 也請遵守 : <a href="https://discord.com/guidelines" target="_blank" rel="noreferrer">Discord社群守則</a></p><h3 id="請勿發送下列言論" tabindex="-1">請勿發送下列言論 <a class="header-anchor" href="#請勿發送下列言論" aria-label="Permalink to &quot;請勿發送下列言論&quot;">​</a></h3><ul><li>『辱罵、誹謗、侮辱、威脅、嚴重歧視特定族群、嚴重冒犯他人、攻擊性言論』... <ul><li>主要針對於玩家之間的衝突言論，若您有不喜歡之玩家，請善用禁言或Discord封鎖功能，而不是擴大衝突或製造更多爭端。</li></ul></li><li>『違法行為之討論、違反善良風俗、客觀上令人不適之言論...』 <ul><li>發言時請顧及並尊重不同玩家與族群的感受，避免造成他人不適。</li></ul></li><li>『性騷擾或猥褻、明顯不雅字眼』</li><li>當在此頻道發言時，請務必考慮到你的每一句話會被全體玩家所看見。</li><li>相關言詞之認定包含但不限於諧音、注音文...等意圖規避之言論。</li></ul><h3 id="請不要在此頻道與他人爭執或發生衝突" tabindex="-1">請不要在此頻道與他人爭執或發生衝突 <a class="header-anchor" href="#請不要在此頻道與他人爭執或發生衝突" aria-label="Permalink to &quot;請不要在此頻道與他人爭執或發生衝突&quot;">​</a></h3><ul><li>不論爭執事件的是非對錯，請考慮到在此頻道上的其他玩家會<b>被動且強迫的</b>看見你們的爭吵內容，這對於與其他無關的玩家是一則沒有必要的訊息，亦或是一種干擾。 <ul><li>不論爭執的參與者是事件的當事人、當事人朋友、無關的旁觀者...。</li><li>包含當某玩家的行為在你眼中認為是不當行為，進而公開表達個人立場或情緒並當眾指責。</li><li>當該事件與您無關時，請盡量不要加入衝突的參與(這可能反而會助長衝突的擴大)，而是優先聯繫管理員來出面處理。</li></ul></li><li>若與玩家發生衝突，還請在其他非此頻道處理，或是使用客服系統請管理員出面協助。</li><li>嚴禁有<b>引戰</b>等助長衝突之行為發生或意圖。</li></ul><h3 id="請勿洗頻、傳送惡意釣魚連結、散播個人資料" tabindex="-1">請勿<code>洗頻、傳送惡意釣魚連結、散播個人資料</code> <a class="header-anchor" href="#請勿洗頻、傳送惡意釣魚連結、散播個人資料" aria-label="Permalink to &quot;請勿`洗頻、傳送惡意釣魚連結、散播個人資料`&quot;">​</a></h3><ul><li>此類情況會嚴重影響其他玩家的遊玩體驗，我們會加重處理。</li><li>此類情況之認定不限於文字或影音形式。</li><li>洗頻之認定不限於一人或多人參與。</li></ul><h3 id="請勿惡意騷擾玩家" tabindex="-1">請勿惡意騷擾玩家 <a class="header-anchor" href="#請勿惡意騷擾玩家" aria-label="Permalink to &quot;請勿惡意騷擾玩家&quot;">​</a></h3><ul><li>包含上述要點行為，若接收方認為不舒服的，可截圖記錄並檢舉。</li><li>此類狀況包含遊戲或Discord的私人訊息之騷擾。</li></ul><h3 id="請盡量避免將此頻道當作自己的個人群組或私人聊天室" tabindex="-1">請盡量避免將此頻道當作自己的個人群組或私人聊天室 <a class="header-anchor" href="#請盡量避免將此頻道當作自己的個人群組或私人聊天室" aria-label="Permalink to &quot;請盡量避免將此頻道當作自己的個人群組或私人聊天室&quot;">​</a></h3><ul><li>對於其他完全不認識你或是無法參與你的話題的玩家來說，這可能會是一則無法理解且不必要的訊息。</li><li>若為互相熟識之玩家，鼓勵至非此頻道聊天，這樣在聊天時會比較自由，也不會對其他玩家造成干擾。</li><li>同時，也請盡量不要進行廣告之行為。</li></ul><h3 id="內容認定" tabindex="-1">內容認定 <a class="header-anchor" href="#內容認定" aria-label="Permalink to &quot;內容認定&quot;">​</a></h3><ul><li><p>由您的帳號(包含Minecraft帳號/Discord帳號)所發言之任何內容與資訊載體，皆視為由您本人之發言。</p></li><li><p>包括但不限於 : <code>文字、物品、多媒體、貼圖、連結、暱稱、帳號#數字</code>。</p></li><li><p>任何非公開範圍，伺服皆無法得知與保存任何內容</p><ul><li>包含 : 社區頻道/遊戲或Discord私訊/社區私人Discord...。</li><li>伺服任何人包括服主自己，皆不會也<b>無法得知</b>其聊天內容為何，請玩家們放心自由聊天，相關記錄也請自行保存。</li><li>鼓勵玩家多多使用私訊/社區頻道或第三方平台，享受完全由玩家自治的聊天環境。</li></ul></li></ul>',15)])])}const p=i(t,[["render",o]]);export{b as __pageData,p as default};
